package sample.app

import kotlin.js.ExperimentalWasmJsInterop
import kotlin.js.js

/**
 * Tiny, generated, network-independent MKV used by the Wasm sample.
 *
 * It contains VP9 video and two Opus tracks (`en`/440 Hz and `pl`/660 Hz). The sample loops it so the audio-track
 * selector can be exercised immediately. Production applications should use an ordinary URL or FileKit file.
 */
internal const val KMEDIA_WASM_DUAL_OPUS_MKV_DATA_URI =
    "data:video/x-matroska;base64," +
        ""

@OptIn(ExperimentalWasmJsInterop::class)
internal fun createKMediaWasmDualOpusMkvBlobUrl(): String =
    createKMediaWasmDemoBlobUrl(KMEDIA_WASM_DUAL_OPUS_MKV_DATA_URI)

@Suppress("UNUSED_PARAMETER")
@OptIn(ExperimentalWasmJsInterop::class)
private fun createKMediaWasmDemoBlobUrl(dataUri: String): String =
    js(
        """
        (function() {
            const encoded = String(dataUri).split(",", 2)[1] || "";
            const binary = atob(encoded);
            const bytes = new Uint8Array(binary.length);
            for (let index = 0; index < binary.length; index += 1) {
                bytes[index] = binary.charCodeAt(index);
            }
            return URL.createObjectURL(new Blob([bytes], { type: "video/x-matroska" }));
        })()
        """,
    )
